'use client'

import {
  createContext,
  type ComponentProps,
  type ReactElement,
  type ReactNode,
  useContext,
} from 'react'
import {
  Card,
  CardAction,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from '@/components/ui/card'
import { cn } from '../../lib/utils'

export type KanbanCardDisplay = 'full' | 'compact'

export interface KanbanCardProps extends ComponentProps<typeof Card> {
  dimmed?: boolean
  display?: KanbanCardDisplay
  children: ReactNode
}

export type KanbanCardActionProps = ComponentProps<typeof CardAction>
export type KanbanCardContentProps = ComponentProps<typeof CardContent>
export type KanbanCardDescriptionProps = ComponentProps<typeof CardDescription>
export type KanbanCardFooterProps = ComponentProps<typeof CardFooter>
export type KanbanCardHeaderProps = ComponentProps<typeof CardHeader>
export type KanbanCardTitleProps = ComponentProps<typeof CardTitle>

const KanbanCardDisplayContext = createContext<KanbanCardDisplay>('full')

export function KanbanCard({
  children,
  className,
  dimmed = false,
  display = 'full',
  render = <article />,
  ...props
}: KanbanCardProps): ReactElement {
  return (
    <KanbanCardDisplayContext.Provider value={display}>
      <Card
        className={cn('min-w-0 max-w-full overflow-hidden', dimmed && 'opacity-70', className)}
        data-display={display}
        render={render}
        {...props}
      >
        {children}
      </Card>
    </KanbanCardDisplayContext.Provider>
  )
}

export function KanbanCardHeader({ className, ...props }: KanbanCardHeaderProps): ReactElement {
  const display = useContext(KanbanCardDisplayContext)

  return (
    <CardHeader
      className={cn(display === 'compact' && 'flex min-w-0 items-center gap-2 p-3', className)}
      {...props}
    />
  )
}

export function KanbanCardTitle({ className, ...props }: KanbanCardTitleProps): ReactElement {
  const display = useContext(KanbanCardDisplayContext)

  return (
    <CardTitle
      className={cn(
        display === 'compact' && 'min-w-0 flex-1 truncate text-sm leading-normal',
        className,
      )}
      {...props}
    />
  )
}

export function KanbanCardDescription(props: KanbanCardDescriptionProps): ReactElement {
  const display = useContext(KanbanCardDisplayContext)

  return <CardDescription {...props} hidden={display === 'compact' || props.hidden} />
}

export function KanbanCardAction({ className, ...props }: KanbanCardActionProps): ReactElement {
  const display = useContext(KanbanCardDisplayContext)

  return (
    <CardAction
      className={cn(display === 'compact' && 'shrink-0 self-center', className)}
      {...props}
    />
  )
}

export function KanbanCardContent(props: KanbanCardContentProps): ReactElement {
  const display = useContext(KanbanCardDisplayContext)

  return <CardContent {...props} hidden={display === 'compact' || props.hidden} />
}

export function KanbanCardFooter(props: KanbanCardFooterProps): ReactElement {
  const display = useContext(KanbanCardDisplayContext)

  return <CardFooter {...props} hidden={display === 'compact' || props.hidden} />
}

import type { ReactElement } from 'react'
import { Skeleton } from '@/components/ui/skeleton'
import { cn } from '../../lib/utils'
import {
  KanbanCard,
  KanbanCardContent,
  KanbanCardFooter,
  KanbanCardHeader,
  type KanbanCardProps,
} from './kanban-card'

export interface KanbanCardSkeletonProps
  extends Omit<KanbanCardProps, 'aria-busy' | 'aria-label' | 'children' | 'role'> {
  label?: string
}

export function KanbanCardSkeleton({
  className,
  display = 'full',
  label = 'Carregando card',
  ...props
}: KanbanCardSkeletonProps): ReactElement {
  return (
    <KanbanCard
      {...props}
      aria-busy="true"
      aria-label={label}
      className={cn('pointer-events-none select-none', className)}
      display={display}
      role="status"
    >
      <KanbanCardHeader aria-hidden="true">
        <Skeleton className="h-4 w-2/3" />
        {display === 'compact' ? (
          <Skeleton className="h-3 w-8 shrink-0" />
        ) : (
          <div className="grid gap-2">
            <Skeleton className="h-3 w-full" />
            <Skeleton className="h-3 w-4/5" />
          </div>
        )}
      </KanbanCardHeader>
      <KanbanCardContent aria-hidden="true">
        <Skeleton className="h-6 w-12 rounded-full" />
      </KanbanCardContent>
      <KanbanCardFooter aria-hidden="true" className="justify-between gap-4">
        <Skeleton className="h-3 w-16" />
        <Skeleton className="h-3 w-12" />
      </KanbanCardFooter>
    </KanbanCard>
  )
}

import { CollisionPriority } from '@dnd-kit/abstract'
import { useDroppable } from '@dnd-kit/react'
import { EllipsisIcon, PlusIcon } from 'lucide-react'
import type { ReactNode } from 'react'
import { useId } from 'react'
import { Button } from '@/components/ui/button'
import { ScrollArea } from '@/components/ui/scroll-area'
import { cn } from '../../lib/utils'

import { createColumnDropId } from '../lib/drag-and-drop'
import type { KanbanColumnActions, KanbanColumnData } from '../types'
import { KanbanBadge } from './kanban-badge'
import { SortableKanbanCard } from './sortable-kanban-card'

export interface KanbanColumnProps<TCard = unknown> {
  column: KanbanColumnData<TCard>
  renderCard: (card: TCard) => ReactNode
  getKey: (card: TCard) => string | number
  emptyLabel?: string
  className?: string
  getCardDragId?: (card: TCard) => string
  getCardLabel?: (card: TCard) => string
  sortableCards?: boolean
  actions?: KanbanColumnActions
}

function KanbanEmptyState({
  children,
  className,
}: Readonly<{ children: ReactNode; className?: string }>) {
  return (
    <div
      className={cn(
        'min-w-0 max-w-full rounded-md border border-dashed px-3 py-6 text-center text-muted-foreground text-sm',
        className,
      )}
    >
      {children}
    </div>
  )
}

function KanbanColumnHeader<TCard>({
  actions,
  column,
  titleId,
}: Readonly<{
  actions?: KanbanColumnActions
  column: KanbanColumnData<TCard>
  titleId: string
}>) {
  return (
    <header className="mb-3 flex shrink-0 items-center justify-between gap-3 px-3 pt-3">
      <div className="flex min-w-0 items-center gap-2">
        <h2 className="truncate font-semibold text-sm leading-none" id={titleId}>
          {column.title}
        </h2>
        <KanbanBadge tone="neutral">{column.count}</KanbanBadge>
      </div>
      {actions?.onOpenSettings || actions?.onAddCard ? (
        <div className="flex shrink-0 items-center gap-0.5">
          {actions.onOpenSettings ? (
            <Button
              aria-label={actions.settingsLabel ?? `Configurar seção ${column.title}`}
              onClick={() => actions.onOpenSettings?.(column.id)}
              size="icon-xs"
              variant="ghost"
            >
              <EllipsisIcon aria-hidden="true" />
            </Button>
          ) : null}
          {actions.onAddCard ? (
            <Button
              aria-label={actions.addLabel ?? `Adicionar item à seção ${column.title}`}
              onClick={() => actions.onAddCard?.(column.id)}
              size="icon-xs"
              variant="ghost"
            >
              <PlusIcon aria-hidden="true" />
            </Button>
          ) : null}
        </div>
      ) : null}
    </header>
  )
}

interface KanbanColumnCardsProps<TCard> {
  column: KanbanColumnData<TCard>
  emptyLabel: string
  getCardDragId?: (card: TCard) => string
  getCardLabel: (card: TCard) => string
  getKey: (card: TCard) => string | number
  renderCard: (card: TCard) => ReactNode
  sortableCards: boolean
}

function KanbanColumnCards<TCard>({
  column,
  emptyLabel,
  getCardDragId,
  getCardLabel,
  getKey,
  renderCard,
  sortableCards,
}: KanbanColumnCardsProps<TCard>) {
  if (!column.cards.length) {
    return <KanbanEmptyState className="bg-card/60 py-10">{emptyLabel}</KanbanEmptyState>
  }

  if (!sortableCards || !getCardDragId) {
    return column.cards.map((card) => (
      <div className="min-w-0 max-w-full" data-kanban-card-container="" key={getKey(card)}>
        {renderCard(card)}
      </div>
    ))
  }

  return column.cards.map((card, index) => (
    <SortableKanbanCard
      columnId={column.id}
      dragLabel={`Mover card ${getCardLabel(card)}`}
      id={getCardDragId(card)}
      index={index}
      key={getKey(card)}
    >
      {renderCard(card)}
    </SortableKanbanCard>
  ))
}

export function KanbanColumn<TCard>({
  column,
  renderCard,
  getKey,
  emptyLabel = 'Nenhum item nesta coluna.',
  className,
  getCardDragId,
  getCardLabel = (card) => String(getKey(card)),
  sortableCards = false,
  actions,
}: KanbanColumnProps<TCard>) {
  const instanceId = useId()
  const titleId = `kanban-column-title-${instanceId}`
  const { ref } = useDroppable({
    accept: 'kanban-card',
    collisionPriority: CollisionPriority.Lowest,
    id: createColumnDropId(column.id, instanceId),
    data: { columnId: column.id, type: 'column' },
    disabled: !sortableCards,
    type: 'kanban-column',
  })

  return (
    <section
      aria-labelledby={titleId}
      className={cn(
        'flex h-full min-h-0 min-w-0 max-w-full flex-col rounded-lg bg-card/30 shadow-black/5 shadow-inner',
        className,
      )}
    >
      <KanbanColumnHeader column={column} titleId={titleId} {...(actions ? { actions } : {})} />

      <ScrollArea className="min-h-0 flex-1" fill scrollbarGutter scrollFade>
        <div
          ref={ref}
          className="grid h-full min-h-full min-w-0 max-w-full content-start gap-2 px-2 pb-2"
        >
          <KanbanColumnCards
            column={column}
            emptyLabel={emptyLabel}
            getCardLabel={getCardLabel}
            getKey={getKey}
            renderCard={renderCard}
            sortableCards={sortableCards}
            {...(getCardDragId ? { getCardDragId } : {})}
          />
        </div>
      </ScrollArea>
    </section>
  )
}

import { useId } from 'react'
import { Button } from '@/components/ui/button'
import { ScrollArea } from '@/components/ui/scroll-area'

import type { KanbanStageOption } from '../types'

export interface KanbanStageSelectorProps {
  id?: string
  label?: string
  stages: KanbanStageOption[]
  value: string
  onValueChange: (value: string) => void
  hint?: string
}

export function KanbanStageSelector({
  id,
  label = 'Etapa',
  stages,
  value,
  onValueChange,
  hint,
}: KanbanStageSelectorProps) {
  const generatedId = useId()
  const selectorId = id ?? `kanban-stage-${generatedId}`

  return (
    <div className="md:hidden">
      <div className="mb-1.5 font-medium text-muted-foreground text-xs" id={`${selectorId}-label`}>
        {label}
      </div>
      <ScrollArea aria-labelledby={`${selectorId}-label`} className="h-9" scrollbarGutter>
        <div className="flex w-max gap-1">
          {stages.map((stage) => {
            const selected = stage.value === value
            return (
              <Button
                aria-pressed={selected}
                key={stage.value}
                onClick={() => onValueChange(stage.value)}
                size="sm"
                variant={selected ? 'secondary' : 'ghost'}
              >
                {stage.label}
              </Button>
            )
          })}
        </div>
      </ScrollArea>
      {hint ? <p className="mt-2 text-muted-foreground text-xs">{hint}</p> : null}
    </div>
  )
}

import { DragDropProvider, DragOverlay } from '@dnd-kit/react'
import type { ReactNode } from 'react'
import { useLayoutEffect, useMemo, useRef } from 'react'
import { ScrollArea } from '@/components/ui/scroll-area'
import { cn } from '../../lib/utils'

import { useActiveColumnId } from '../hooks/use-active-column-id'
import { useHorizontalDragScroll } from '../hooks/use-horizontal-drag-scroll'
import { useKanbanDragAndDrop } from '../hooks/use-kanban-drag-and-drop'
import type {
  KanbanCardMove,
  KanbanColumnActions,
  KanbanColumnData,
  KanbanStageOption,
} from '../types'
import { KanbanColumn } from './kanban-column'
import { KanbanStageSelector } from './kanban-stage-selector'

export interface KanbanViewProps<TCard = unknown> {
  columns: KanbanColumnData<TCard>[]
  renderCard: (card: TCard) => ReactNode
  getKey: (card: TCard) => string | number
  getCardLabel?: (card: TCard) => string
  getColumnActions?: (column: KanbanColumnData<TCard>) => KanbanColumnActions | undefined
  emptyColumnLabel?: string
  mobileStageHint?: string
  onMoveCard?: (move: KanbanCardMove<TCard>) => boolean | Promise<boolean>
}

export function KanbanView<TCard>({
  columns,
  renderCard,
  getKey,
  getCardLabel,
  getColumnActions,
  emptyColumnLabel,
  mobileStageHint,
  onMoveCard,
}: KanbanViewProps<TCard>) {
  const [activeColumnId, setActiveColumnId] = useActiveColumnId(columns)
  const {
    cardDragEnabled,
    focusCardDragId,
    getCardDragId,
    handleCardFocusRestored,
    handleDragEnd,
    handleDragOver,
    handleDragStart,
    visibleColumns,
  } = useKanbanDragAndDrop({ columns, getKey, ...(onMoveCard ? { onMoveCard } : {}) })
  const { isDragging: isBoardDragging, rootRef } = useHorizontalDragScroll()
  const boardContentRef = useRef<HTMLDivElement | null>(null)
  const stageOptions = useMemo(() => createStageOptions(columns), [columns])
  const cardsByDragId = useMemo(
    () =>
      new Map(
        visibleColumns.flatMap((column) =>
          column.cards.map((card) => [getCardDragId(card), card] as const),
        ),
      ),
    [getCardDragId, visibleColumns],
  )
  const activeColumn = useMemo(
    () => visibleColumns.find((column) => column.id === activeColumnId) ?? visibleColumns[0],
    [activeColumnId, visibleColumns],
  )
  const columnProps = {
    getCardDragId,
    getKey,
    renderCard,
    sortableCards: cardDragEnabled,
    ...(emptyColumnLabel ? { emptyLabel: emptyColumnLabel } : {}),
    ...(getCardLabel ? { getCardLabel } : {}),
  }
  const showHorizontalScrollbar = cardDragEnabled && isBoardDragging
  const getColumnActionProps = (column: KanbanColumnData<TCard>) => {
    const actions = getColumnActions?.(column)
    return actions ? { actions } : {}
  }

  useLayoutEffect(() => {
    if (!focusCardDragId) return

    const frame = requestAnimationFrame(() => {
      const card = Array.from(
        boardContentRef.current?.querySelectorAll<HTMLElement>('[data-kanban-card-drag-id]') ?? [],
      ).find((element) => element.getAttribute('data-kanban-card-drag-id') === focusCardDragId)

      if (!card) return
      card.focus({ preventScroll: true })
      card.scrollIntoView({ behavior: 'instant', block: 'nearest', inline: 'nearest' })
      handleCardFocusRestored()
    })

    return () => cancelAnimationFrame(frame)
  }, [focusCardDragId, handleCardFocusRestored])

  return (
    <div className="h-full min-h-0">
      <DragDropProvider
        onDragEnd={handleDragEnd}
        onDragOver={handleDragOver}
        onDragStart={handleDragStart}
      >
        <div className="flex h-full min-h-0 flex-col gap-2">
          <KanbanStageSelector
            onValueChange={setActiveColumnId}
            stages={stageOptions}
            value={activeColumnId}
            {...(mobileStageHint ? { hint: mobileStageHint } : {})}
          />

          <div className="grid min-h-0 flex-1 gap-2 md:hidden">
            {activeColumn ? (
              <KanbanColumn
                column={activeColumn}
                {...columnProps}
                sortableCards={false}
                {...getColumnActionProps(activeColumn)}
              />
            ) : null}
          </div>

          <ScrollArea
            className={cn(
              'hidden min-h-0 flex-1 md:block',
              '[&_[data-orientation=horizontal][data-slot=scroll-area-scrollbar]]:!delay-0',
              showHorizontalScrollbar
                ? '[&_[data-orientation=horizontal][data-slot=scroll-area-scrollbar]]:!opacity-100'
                : '[&_[data-orientation=horizontal][data-slot=scroll-area-scrollbar]]:!pointer-events-none [&_[data-orientation=horizontal][data-slot=scroll-area-scrollbar]]:!opacity-0',
              cardDragEnabled
                ? '[&_[data-slot=scroll-area-viewport]]:cursor-grab [&_[data-slot=scroll-area-viewport]]:select-none'
                : '[&_[data-slot=scroll-area-viewport]]:cursor-default',
              showHorizontalScrollbar && '[&_[data-slot=scroll-area-viewport]]:cursor-grabbing',
            )}
            data-kanban-board-scroll-area=""
            data-kanban-horizontal-scrollbar={showHorizontalScrollbar ? 'visible' : 'hidden'}
            fill
            ref={cardDragEnabled ? rootRef : undefined}
            scrollbarGutter
            scrollFade
          >
            <div
              className="grid h-full min-h-full w-max auto-cols-[minmax(19rem,22rem)] grid-flow-col gap-2"
              ref={boardContentRef}
            >
              {visibleColumns.map((column) => (
                <KanbanColumn
                  column={column}
                  key={column.id}
                  {...columnProps}
                  {...getColumnActionProps(column)}
                />
              ))}
            </div>
          </ScrollArea>
        </div>
        <DragOverlay className="pointer-events-none" dropAnimation={null}>
          {(source) => {
            const card = cardsByDragId.get(String(source.id))
            return card ? renderCard(card) : null
          }}
        </DragOverlay>
      </DragDropProvider>
    </div>
  )
}

function createStageOptions(columns: KanbanColumnData[]): KanbanStageOption[] {
  return columns.map((column) => ({
    label: `${column.title} · ${column.count}`,
    value: column.id,
  }))
}

import { pointerIntersection } from '@dnd-kit/collision'
import { KeyboardSensor, PointerSensor } from '@dnd-kit/dom'
import { useSortable } from '@dnd-kit/react/sortable'
import type { PointerEvent as ReactPointerEvent, ReactNode } from 'react'
import { useCallback, useLayoutEffect, useRef } from 'react'
import { cn } from '../../lib/utils'

const ACTIONABLE_DESCENDANT_SELECTOR = [
  'a[href]:not([data-kanban-card-action])',
  'button:not([disabled]):not([data-kanban-card-action])',
  '[role="button"]:not([aria-disabled="true"]):not([data-kanban-card-action])',
  '[role="link"]:not([aria-disabled="true"]):not([data-kanban-card-action])',
].join(',')

const KANBAN_CARD_SENSORS = [
  PointerSensor,
  KeyboardSensor.configure({
    keyboardCodes: {
      cancel: ['Escape'],
      down: ['ArrowDown'],
      end: ['Space', 'Tab'],
      left: ['ArrowLeft'],
      right: ['ArrowRight'],
      start: ['Space'],
      up: ['ArrowUp'],
    },
  }),
]

interface SortableKanbanCardProps {
  children: ReactNode
  columnId: string
  dragLabel: string
  id: string
  index: number
}

export function SortableKanbanCard({
  children,
  columnId,
  dragLabel,
  id,
  index,
}: SortableKanbanCardProps) {
  const { handleRef, isDragSource, ref } = useSortable({
    accept: 'kanban-card',
    collisionDetector: pointerIntersection,
    data: { cardId: id, columnId, type: 'card' },
    group: columnId,
    id,
    index,
    sensors: KANBAN_CARD_SENSORS,
    transition: null,
    type: 'kanban-card',
  })
  const wrapperRef = useRef<HTMLElement | null>(null)
  const setWrapperRef = useCallback(
    (node: HTMLElement | null) => {
      wrapperRef.current = node
      ref(node)
    },
    [ref],
  )

  useLayoutEffect(() => {
    const wrapper = wrapperRef.current
    const contentActivator = wrapper?.querySelector<HTMLElement>(ACTIONABLE_DESCENDANT_SELECTOR)

    handleRef(contentActivator ?? wrapper)
    return () => handleRef(null)
  })

  const handlePointerDownCapture = (event: ReactPointerEvent<HTMLElement>) => {
    const target = event.target
    if (target instanceof Element && target.closest('[data-kanban-card-action]')) {
      event.stopPropagation()
    }
  }

  return (
    <section
      aria-label={dragLabel}
      className={cn(
        'relative min-w-0 max-w-full touch-none rounded-lg outline-none focus-visible:ring-2 focus-visible:ring-ring',
        'cursor-grab active:cursor-grabbing',
        isDragSource && 'opacity-0',
      )}
      data-kanban-card-container=""
      data-kanban-card-drag-id={id}
      data-kanban-card-draggable=""
      onPointerDownCapture={handlePointerDownCapture}
      ref={setWrapperRef}
    >
      {children}
    </section>
  )
}

import { useEffect, useState } from 'react'

import type { KanbanColumnData } from '../types'

export function useActiveColumnId(columns: KanbanColumnData[]): [string, (id: string) => void] {
  const [activeColumnId, setActiveColumnId] = useState(columns[0]?.id ?? '')

  useEffect(() => {
    if (!columns.some((column) => column.id === activeColumnId)) {
      setActiveColumnId(columns[0]?.id ?? '')
    }
  }, [activeColumnId, columns])

  return [activeColumnId, setActiveColumnId]
}

import { useCallback, useEffect, useRef, useState } from 'react'

const DRAG_THRESHOLD = 8
const CLICK_SUPPRESSION_WINDOW_MS = 500
const EXCLUDED_TARGETS = [
  'a',
  'button',
  'input',
  'select',
  'textarea',
  '[contenteditable="true"]',
  '[role="button"]',
  '[role="link"]',
  '[role="menuitem"]',
  '[role="option"]',
  '[role="slider"]',
  '[data-kanban-card-draggable]',
  '[data-slot="scroll-area-scrollbar"]',
].join(',')

interface DragOrigin {
  pointerId: number
  scrollLeft: number
  x: number
  y: number
  dragging: boolean
}

interface ReleasedDrag {
  at: number
  x: number
  y: number
}

function isExcludedTarget(target: EventTarget | null): boolean {
  return target instanceof Element && target.closest(EXCLUDED_TARGETS) !== null
}

export function useHorizontalDragScroll() {
  const dragOriginRef = useRef<DragOrigin | null>(null)
  const releasedDragRef = useRef<ReleasedDrag | null>(null)
  const [isDragging, setIsDragging] = useState(false)
  const [rootElement, setRootElement] = useState<HTMLDivElement | null>(null)

  const resetDrag = useCallback(() => {
    dragOriginRef.current = null
    setIsDragging(false)
  }, [])

  useEffect(() => {
    const viewport = rootElement?.querySelector<HTMLDivElement>(
      '[data-slot="scroll-area-viewport"]',
    )
    if (!viewport) return

    const handlePointerDown = (event: PointerEvent) => {
      if (event.button !== 0 || !event.isPrimary || isExcludedTarget(event.target)) return

      releasedDragRef.current = null
      dragOriginRef.current = {
        dragging: false,
        pointerId: event.pointerId,
        scrollLeft: viewport.scrollLeft,
        x: event.clientX,
        y: event.clientY,
      }
    }

    const handlePointerMove = (event: PointerEvent) => {
      const origin = dragOriginRef.current
      if (!origin || origin.pointerId !== event.pointerId) return

      const deltaX = event.clientX - origin.x
      const deltaY = event.clientY - origin.y

      if (!origin.dragging) {
        if (Math.abs(deltaX) < DRAG_THRESHOLD && Math.abs(deltaY) < DRAG_THRESHOLD) return
        if (Math.abs(deltaX) <= Math.abs(deltaY)) {
          dragOriginRef.current = null
          return
        }

        origin.dragging = true
        viewport.setPointerCapture?.(event.pointerId)
        setIsDragging(true)
      }

      event.preventDefault()
      const maximumScrollLeft = Math.max(0, viewport.scrollWidth - viewport.clientWidth)
      viewport.scrollLeft = Math.min(maximumScrollLeft, Math.max(0, origin.scrollLeft - deltaX))
    }

    const handlePointerEnd = (event: PointerEvent) => {
      const origin = dragOriginRef.current
      if (!origin || origin.pointerId !== event.pointerId) return

      if (origin.dragging) {
        releasedDragRef.current = { at: Date.now(), x: event.clientX, y: event.clientY }
        if (viewport.hasPointerCapture?.(event.pointerId)) {
          viewport.releasePointerCapture(event.pointerId)
        }
      }

      resetDrag()
    }

    const handleClickCapture = (event: MouseEvent) => {
      const releasedDrag = releasedDragRef.current
      if (!releasedDrag) return

      releasedDragRef.current = null
      const isReleasedDragClick =
        Date.now() - releasedDrag.at <= CLICK_SUPPRESSION_WINDOW_MS &&
        Math.abs(event.clientX - releasedDrag.x) <= 1 &&
        Math.abs(event.clientY - releasedDrag.y) <= 1

      if (isReleasedDragClick) {
        event.preventDefault()
        event.stopPropagation()
      }
    }

    viewport.addEventListener('click', handleClickCapture, true)
    viewport.addEventListener('lostpointercapture', resetDrag)
    viewport.addEventListener('pointercancel', handlePointerEnd)
    viewport.addEventListener('pointerdown', handlePointerDown)
    viewport.addEventListener('pointermove', handlePointerMove)
    viewport.addEventListener('pointerup', handlePointerEnd)

    return () => {
      resetDrag()
      viewport.removeEventListener('click', handleClickCapture, true)
      viewport.removeEventListener('lostpointercapture', resetDrag)
      viewport.removeEventListener('pointercancel', handlePointerEnd)
      viewport.removeEventListener('pointerdown', handlePointerDown)
      viewport.removeEventListener('pointermove', handlePointerMove)
      viewport.removeEventListener('pointerup', handlePointerEnd)
    }
  }, [resetDrag, rootElement])

  return {
    isDragging,
    rootRef: setRootElement,
  }
}

import type { DragEndEvent, DragOverEvent, DragStartEvent } from '@dnd-kit/react'
import { useCallback, useEffect, useRef, useState } from 'react'

import {
  createCardDragId,
  findCardLocation,
  projectKanbanColumns,
  resolveKanbanCardMove,
} from '../lib/drag-and-drop'
import type { KanbanCardMove, KanbanColumnData } from '../types'

interface UseKanbanDragAndDropOptions<TCard> {
  columns: KanbanColumnData<TCard>[]
  getKey: (card: TCard) => string | number
  onMoveCard?: (move: KanbanCardMove<TCard>) => boolean | Promise<boolean>
}

interface PendingCardMove {
  accepted: boolean
  cardDragId: string
  requestId: number
  targetColumnId: string
  targetIndex?: number
}

export function useKanbanDragAndDrop<TCard>({
  columns,
  getKey,
  onMoveCard,
}: UseKanbanDragAndDropOptions<TCard>) {
  const [optimisticColumns, setOptimisticColumns] = useState<KanbanColumnData<TCard>[] | null>(null)
  const [focusCardDragId, setFocusCardDragId] = useState<string | null>(null)
  const columnsRef = useRef(columns)
  const optimisticColumnsRef = useRef<KanbanColumnData<TCard>[] | null>(null)
  const dragSourceColumnsRef = useRef<KanbanColumnData<TCard>[] | null>(null)
  const rollbackSourceColumnsRef = useRef<KanbanColumnData<TCard>[] | null>(null)
  const pendingCardMoveRef = useRef<PendingCardMove | null>(null)
  const moveRequestIdRef = useRef(0)
  columnsRef.current = columns

  const getCardDragId = useCallback((card: TCard) => createCardDragId(getKey(card)), [getKey])
  const updateOptimisticColumns = useCallback((nextColumns: KanbanColumnData<TCard>[] | null) => {
    if (optimisticColumnsRef.current === nextColumns) return
    optimisticColumnsRef.current = nextColumns
    setOptimisticColumns(nextColumns)
  }, [])

  useEffect(() => {
    const rollbackSourceColumns = rollbackSourceColumnsRef.current
    if (rollbackSourceColumns && columns !== rollbackSourceColumns) {
      rollbackSourceColumnsRef.current = null
      updateOptimisticColumns(null)
      return
    }

    const pendingCardMove = pendingCardMoveRef.current
    if (!pendingCardMove?.accepted) return
    if (!isPendingCardMoveConfirmed(columns, pendingCardMove, getCardDragId)) return

    pendingCardMoveRef.current = null
    updateOptimisticColumns(null)
  }, [columns, getCardDragId, updateOptimisticColumns])

  const handleDragStart = useCallback((_event: DragStartEvent) => {
    setFocusCardDragId(null)
    dragSourceColumnsRef.current = optimisticColumnsRef.current ?? columnsRef.current
  }, [])
  const handleCardFocusRestored = useCallback(() => setFocusCardDragId(null), [])

  const handleDragOver = useCallback(
    (event: DragOverEvent) => {
      const { source, target } = event.operation
      const { type: sourceType } = source?.data ?? {}
      const { type: targetType } = target?.data ?? {}

      if (!onMoveCard || sourceType !== 'card' || targetType !== 'column') {
        return
      }

      const visibleColumns =
        optimisticColumnsRef.current ?? dragSourceColumnsRef.current ?? columnsRef.current
      const projectedColumns = projectKanbanColumns(visibleColumns, event, getCardDragId)

      if (projectedColumns !== visibleColumns) updateOptimisticColumns(projectedColumns)
    },
    [getCardDragId, onMoveCard, updateOptimisticColumns],
  )

  const handleDragEnd = useCallback(
    (event: DragEndEvent) => {
      const sourceColumns = dragSourceColumnsRef.current ?? columnsRef.current
      dragSourceColumnsRef.current = null

      if (event.canceled) {
        if (!pendingCardMoveRef.current) updateOptimisticColumns(null)
        return
      }

      const visibleColumns = optimisticColumnsRef.current ?? sourceColumns
      const projectedColumns = projectKanbanColumns(visibleColumns, event, getCardDragId)
      const move = resolveKanbanCardMove(sourceColumns, projectedColumns, event, getCardDragId)

      if (!move || !onMoveCard) {
        if (!pendingCardMoveRef.current) updateOptimisticColumns(null)
        return
      }

      if (move.sourceColumnId !== move.targetColumnId) {
        setFocusCardDragId(String(event.operation.source?.id))
      }
      updateOptimisticColumns(projectedColumns)
      rollbackSourceColumnsRef.current = null
      const requestId = moveRequestIdRef.current + 1
      moveRequestIdRef.current = requestId
      pendingCardMoveRef.current = {
        accepted: false,
        cardDragId: String(event.operation.source?.id),
        requestId,
        targetColumnId: move.targetColumnId,
        ...(move.targetIndex === undefined ? {} : { targetIndex: move.targetIndex }),
      }
      const suspension = event.suspend()

      const settleCardMove = (accepted: boolean, settleSuspension: boolean) => {
        const pendingCardMove = pendingCardMoveRef.current
        if (!pendingCardMove || pendingCardMove.requestId !== requestId) return

        if (!accepted) {
          pendingCardMoveRef.current = null
          if (settleSuspension) suspension.abort()
          rollbackSourceColumnsRef.current = sourceColumns
          updateOptimisticColumns(cloneColumnOrder(sourceColumns))
          return
        }

        pendingCardMove.accepted = true
        if (settleSuspension) suspension.resume()
        if (!isPendingCardMoveConfirmed(columnsRef.current, pendingCardMove, getCardDragId)) return

        pendingCardMoveRef.current = null
        updateOptimisticColumns(null)
      }

      try {
        const moveAccepted = onMoveCard(move)

        if (isPromiseLike(moveAccepted)) {
          // Holding a suspended operation across network latency keeps the
          // drag feedback active after pointer-up. Finish the native drop now;
          // the optimistic columns below own cache reconciliation only.
          suspension.resume()
          void Promise.resolve(moveAccepted).then(
            (accepted) => settleCardMove(accepted, false),
            () => settleCardMove(false, false),
          )
        } else {
          settleCardMove(moveAccepted, true)
        }
      } catch {
        settleCardMove(false, true)
      }
    },
    [getCardDragId, onMoveCard, updateOptimisticColumns],
  )

  return {
    cardDragEnabled: Boolean(onMoveCard),
    focusCardDragId,
    getCardDragId,
    handleCardFocusRestored,
    handleDragEnd,
    handleDragOver,
    handleDragStart,
    visibleColumns: optimisticColumns ?? columns,
  }
}

function isPendingCardMoveConfirmed<TCard>(
  columns: KanbanColumnData<TCard>[],
  pendingCardMove: PendingCardMove,
  getCardDragId: (card: TCard) => string,
): boolean {
  const cardLocation = findCardLocation(columns, pendingCardMove.cardDragId, getCardDragId)

  return (
    cardLocation?.columnId === pendingCardMove.targetColumnId &&
    (pendingCardMove.targetIndex === undefined ||
      cardLocation.cardIndex === pendingCardMove.targetIndex)
  )
}

function isPromiseLike(value: boolean | Promise<boolean>): value is Promise<boolean> {
  return typeof value === 'object' && value !== null && 'then' in value
}

function cloneColumnOrder<TCard>(columns: KanbanColumnData<TCard>[]): KanbanColumnData<TCard>[] {
  return columns.map((column) => ({ ...column, cards: [...column.cards] }))
}

import { move } from '@dnd-kit/helpers'
import type { DragEndEvent, DragOverEvent } from '@dnd-kit/react'

import type { KanbanCardMove, KanbanColumnData } from '../types'

const CARD_DRAG_PREFIX = 'kanban-card:'
const COLUMN_DROP_PREFIX = 'kanban-column:'

type DragIdentifier = string | number
type KanbanDragEvent = DragEndEvent | DragOverEvent

interface ProjectedCard<TCard> {
  card: TCard
  id: string
}

export interface CardLocation<TCard> {
  card: TCard
  cardIndex: number
  columnId: string
  columnIndex: number
}

export function createCardDragId(cardId: DragIdentifier): string {
  return `${CARD_DRAG_PREFIX}${String(cardId)}`
}

export function parseCardDragId(id: DragIdentifier): string {
  return String(id).replace(new RegExp(`^${CARD_DRAG_PREFIX}`), '')
}

export function createColumnDropId(columnId: string, instanceId?: string): string {
  const columnPart = encodeURIComponent(columnId)
  const instancePart = instanceId ? `:${encodeURIComponent(instanceId)}` : ''

  return `${COLUMN_DROP_PREFIX}${columnPart}${instancePart}`
}

export function parseColumnId(id: DragIdentifier): string {
  const value = String(id)

  if (!value.startsWith(COLUMN_DROP_PREFIX)) return ''

  const encodedColumnId = value.slice(COLUMN_DROP_PREFIX.length).split(':', 1)[0] ?? ''

  try {
    return decodeURIComponent(encodedColumnId)
  } catch {
    return encodedColumnId
  }
}

export function findCardLocation<TCard>(
  columns: KanbanColumnData<TCard>[],
  cardDragId: string,
  getCardDragId: (card: TCard) => DragIdentifier,
): CardLocation<TCard> | undefined {
  for (const [columnIndex, column] of columns.entries()) {
    const cardIndex = column.cards.findIndex((card) => String(getCardDragId(card)) === cardDragId)

    if (cardIndex !== -1) {
      return {
        card: column.cards[cardIndex]!,
        cardIndex,
        columnId: column.id,
        columnIndex,
      }
    }
  }
}

/**
 * Projects the consumer's columns with dnd-kit's official `move` helper.
 * Sortable cards use the indices and groups maintained by the library. A plain
 * column target only adapts the instance-scoped droppable id to the logical
 * column id, which is the additional case required for empty lists.
 */
export function projectKanbanColumns<TCard>(
  columns: KanbanColumnData<TCard>[],
  event: KanbanDragEvent,
  getCardDragId: (card: TCard) => DragIdentifier,
): KanbanColumnData<TCard>[] {
  const target = event.operation.target
  const { columnId, type: targetType } = target?.data ?? {}
  const targetColumnId =
    targetType === 'column' && typeof columnId === 'string' ? columnId : undefined
  const collectionKeys = new Map<string, string>()
  const collections = Object.fromEntries(
    columns.map((column) => {
      const collectionKey = column.id === targetColumnId && target ? String(target.id) : column.id
      collectionKeys.set(column.id, collectionKey)

      return [
        collectionKey,
        column.cards.map((card) => ({ card, id: String(getCardDragId(card)) })),
      ]
    }),
  ) as Record<string, ProjectedCard<TCard>[]>
  const projectedCollections = move(collections, event)

  if (projectedCollections === collections) return columns

  let changed = false
  const projectedColumns = columns.map((column) => {
    const collectionKey = collectionKeys.get(column.id)
    const projectedCards = collectionKey
      ? projectedCollections[collectionKey]?.map(({ card }) => card)
      : undefined

    if (!projectedCards || hasSameCardOrder(column.cards, projectedCards, getCardDragId)) {
      return column
    }

    changed = true
    return { ...column, cards: projectedCards, count: projectedCards.length }
  })

  return changed ? projectedColumns : columns
}

export function resolveKanbanCardMove<TCard>(
  sourceColumns: KanbanColumnData<TCard>[],
  projectedColumns: KanbanColumnData<TCard>[],
  event: DragEndEvent,
  getCardDragId: (card: TCard) => DragIdentifier,
): KanbanCardMove<TCard> | undefined {
  const source = event.operation.source
  const { type: sourceType } = source?.data ?? {}

  if (event.canceled || !source || sourceType !== 'card') return undefined

  const cardDragId = String(source.id)
  const sourceLocation = findCardLocation(sourceColumns, cardDragId, getCardDragId)
  const targetLocation = findCardLocation(projectedColumns, cardDragId, getCardDragId)

  if (
    !sourceLocation ||
    !targetLocation ||
    (sourceLocation.columnId === targetLocation.columnId &&
      sourceLocation.cardIndex === targetLocation.cardIndex)
  ) {
    return undefined
  }

  return {
    card: sourceLocation.card,
    cardId: parseCardDragId(cardDragId),
    sourceColumnId: sourceLocation.columnId,
    sourceIndex: sourceLocation.cardIndex,
    targetColumnId: targetLocation.columnId,
    targetIndex: targetLocation.cardIndex,
  }
}

function hasSameCardOrder<TCard>(
  currentCards: TCard[],
  projectedCards: TCard[],
  getCardDragId: (card: TCard) => DragIdentifier,
): boolean {
  return (
    currentCards.length === projectedCards.length &&
    currentCards.every(
      (card, index) =>
        String(getCardDragId(card)) === String(getCardDragId(projectedCards[index]!)),
    )
  )
}

